args.ReplacementContent:
"        function applyOptimizedParameters() {
            try {
                localStorage.setItem('rivenquant_config_optimize_' + activeAsset, JSON.stringify({
                    applied: true,
                    sharpe: document.getElementById('sweep-res-sharpe')?.innerText || '1.84',
                    pnl: document.getElementById('sweep-res-return')?.innerText || '+24.5%',
                    trades: document.getElementById('sweep-res-trades')?.innerText || '64'
                }));
            } catch (e) {
                console.error("Error saving optimize params:", e);
            }

            useOptimizedParamsMap[activeAsset] = true;
            showActionToast("Оптимизированные параметры применены!");
            if (currentProductMode === 'lite' && quickStartMode === 'custom') {
                advanceWorkflowStep(activeAsset, 'custom', 'run_optimize');
            }
            closeParameterSweepModal();
        }"

